WITH filtered AS (SELECT id, product_name, category, price, cost, stock_qty, launch_date, tags, DAY(launch_date) AS launch_date_day FROM products WHERE launch_date > DATE '2023-08-24' AND supplier_id IS NOT NULL) SELECT CASE WHEN stock_qty >= 405 THEN 'LARGE' ELSE 'SMALL' END AS stock_qty_tier, category, SUM(cost) FILTER (WHERE category = 'Home') AS home_total_cost, SIZE(COLLECT_SET(category)) AS num_categories, CORR(stock_qty, cost) AS corr_stock_qty_cost, AVG(stock_qty) FILTER (WHERE category = 'Fashion') AS fashion_avg_stock_qty, COUNT_IF(category = 'Home') AS home_events FROM filtered GROUP BY GROUPING SETS ((CASE WHEN stock_qty >= 405 THEN 'LARGE' ELSE 'SMALL' END, category), (CASE WHEN stock_qty >= 405 THEN 'LARGE' ELSE 'SMALL' END)) ORDER BY corr_stock_qty_cost NULLS LAST;
